// Sheet 06's slider handles expose Chinese aria-labels (attributes, not <text>).
const EN_ATTR = {
  '早高峰量': 'AM peak volume',
  '晚高峰量': 'PM peak volume',
  '波形陡峭度': 'Peak width',
  '开站时间': 'Opens',
  '关站时间': 'Closes',
  '早高峰开始': 'AM peak starts',
  '早高峰结束': 'AM peak ends',
  '晚高峰开始': 'PM peak starts',
  '晚高峰结束': 'PM peak ends',
};

// Sheet 06's live readout rebuilds its line from these literals while dragging.
const EN_SCRIPT = {
  '营业 ': 'Open ',
  '早高峰 ': 'AM peak ',
  '晚高峰 ': 'PM peak ',
};

const CJK = /[㐀-䶿一-鿿豈-﫿]+/;

/** English copy can use plain `&`; SVG text and attributes cannot. */
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

/**
 * Rewrite a generated (Chinese) sheet in English. Returns the rewritten SVG
 * plus every Chinese string with no table entry, so gaps fail loudly instead
 * of shipping half-translated.
 */
export function toEnglish(svg) {
  const missing = new Set();
  // Whole <text> contents first (attributes preserved untouched).
  let sizePatches = [];
  let out = svg.replace(/<text\b([^>]*)>([^<]*)<\/text>/g, (m, attrs, inner) => {
    const patch = {};
    let next = inner;
    if (CJK.test(inner)) {
      if (Object.hasOwn(EN, inner)) {
        const v = EN[inner];
        if (typeof v === 'string') next = esc(v);
        else {
          next = esc(v.t);
          patch.size = v.size;
        }
      } else {
        const t = inner.trim();
        if (Object.hasOwn(EN, t)) {
          const v = EN[t];
          const body = esc(typeof v === 'string' ? v : v.t);
          if (typeof v !== 'string') patch.size = v.size;
          const i = inner.indexOf(t);
          next = inner.slice(0, i) + body + inner.slice(i + t.length);
        } else missing.add(inner);
      }
    }
    let a = attrs;
    if (patch.size) {
      a = /font-size="[\d.]+"/.test(attrs)
        ? attrs.replace(/font-size="[\d.]+"/, `font-size="${patch.size}"`)
        : `${attrs} font-size="${patch.size}"`;
      sizePatches.push(next);
    }
    return `<text${a}>${next}</text>`;
  });
  // aria-labels on the interactive handles.
  out = out.replace(/aria-label="([^"]*)"/g, (m, v) =>
    CJK.test(v) && Object.hasOwn(EN_ATTR, v) ? `aria-label="${esc(EN_ATTR[v])}"` : (CJK.test(v) && missing.add(`aria:${v}`), m),
  );
  // Script literals the live readout rebuilds from (longest first).
  for (const k of Object.keys(EN_SCRIPT).sort((a, b) => b.length - a.length)) {
    out = out.split(k).join(EN_SCRIPT[k]);
  }
  // Anything Chinese left is either a gap or a false friend — report it.
  for (const m of out.matchAll(/<text\b[^>]*>([^<]*)<\/text>/g)) {
    if (CJK.test(m[1]) && !Object.hasOwn(EN, m[1].trim())) missing.add(m[1]);
  }
  return { svg: out, missing: [...missing] };
}

/** Every Chinese string across the built sheets, for coverage checks. */
export function auditZh(svg) {
  const found = new Set();
  for (const m of svg.matchAll(/<text\b[^>]*>([^<]*)<\/text>/g)) {
    if (CJK.test(m[1])) found.add(m[1].trim());
  }
  for (const m of svg.matchAll(/aria-label="([^"]*)"/g)) {
    if (CJK.test(m[1])) found.add(`aria:${m[1]}`);
  }
  return [...found];
}
